package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.File;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Date;
import java.util.List;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ZipArchiveEntry#isUnixSymlink
 */
public class ZipArchiveEntry_isUnixSymlink_TriageGen0Test {

    /**
     * Test case where the Unix mode is exactly the LINK_FLAG.
     * This should return true.
     */
    @Test
    public void testIsUnixSymlink_WithLinkFlag() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test_link");
        // Set the mode such that (mode & FILE_TYPE_FLAG) == LINK_FLAG
        int mode = UnixStat.LINK_FLAG;
        entry.setUnixMode(mode);

        assertTrue("Should return true when mode matches LINK_FLAG", entry.isUnixSymlink());
    }

    /**
     * Test case where the Unix mode is greater than the LINK_FLAG (e.g., a specific type of link).
     * This should return true.
     */
    @Test
    public void testIsUnixSymlink_WithHigherThanLinkFlag() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test_link_high");
        // Ensure the bitwise AND results in a value >= LINK_FLAG
        // We use a bitwise OR to ensure the FILE_TYPE_FLAG bits are set
        int mode = UnixStat.FILE_TYPE_FLAG | UnixStat.LINK_FLAG | 0x100; 
        entry.setUnixMode(mode);

        assertTrue("Should return true when mode is greater than LINK_FLAG", entry.isUnixSymlink());
    }

    /**
     * Test case where the Unix mode is 0.
     * This should return false.
     */
    @Test
    public void testIsUnixSymlink_WithZeroMode() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test_zero");
        entry.setUnixMode(0);

        assertFalse("Should return false when mode is 0", entry.isUnixSymlink());
    }

    /**
     * Test case where the Unix mode is a regular file (not a link).
     * This should return false.
     */
    @Test
    public void testIsUnixSymlink_WithRegularFile() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test_file");
        // Regular file flag is typically 0x8000 in UnixStat, which is < LINK_FLAG (0xA000)
        // We set it explicitly to ensure it's below the LINK_FLAG threshold
        int regularFileMode = 0x8000; 
        entry.setUnixMode(regularFileMode);

        // To be safe and follow the logic: (mode & FILE_TYPE_FLAG) must be < LINK_FLAG
        // We force the bitwise result to be less than LINK_FLAG
        int mode = regularFileMode & UnixStat.FILE_TYPE_FLAG;
        // Ensure mode is not a link
        if (mode >= UnixStat.LINK_FLAG) {
            mode = 0; // fallback for test stability
        }
        entry.setUnixMode(mode);

        assertFalse("Should return false for regular files", entry.isUnixSymlink());
    }

    /**
     * Test case where the Unix mode has bits set that are not the FILE_TYPE_FLAG.
     * This should return false if the resulting AND is less than LINK_FLAG.
     */
    @Test
    public void testIsUnixSymlink_WithIrrelevantBits() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test_irrelevant");
        // Set bits that don't affect the FILE_TYPE_FLAG comparison or result in a value < LINK_FLAG
        int mode = 0x1; 
        entry.setUnixMode(mode);

        assertFalse("Should return false when bitwise result is less than LINK_FLAG", entry.isUnixSymlink());
    }
}
